package com.primehr.evidence;
import com.primehr.evidence.domain.*;import org.junit.jupiter.api.Test;import java.time.*;import static org.assertj.core.api.Assertions.*;
class EvidenceFrameworkDomainTest{
 @Test void publishedFrameworkIsImmutableAndLabelsRemainReferenceOnly(){var f=new EvidenceFrameworkVersion("A","F",1,null,"PRIME-ESG Internal Readiness",null,"CSC","MC 11 s. 2026","Agency authority","Internal self-assessment only; not an official CSC determination");f.contentChanged();f.publish(LocalDate.of(2026,10,18),null,"admin",Instant.now());assertThat(f.getStatus()).isEqualTo(EvidenceDefinitionStatus.PUBLISHED);assertThatThrownBy(()->f.update("Changed",null,"CSC","basis","authority","disclaimer")).isInstanceOf(RuntimeException.class);var level=new EvidenceGovernanceLevel("A","V","GL1","Governance Level 1","Reference label",1);assertThat(level.isReferenceOnly()).isTrue();}
 @Test void requirementRejectsInvalidFreshnessAndFrameworkRejectsInvalidEffectivity(){assertThatThrownBy(()->new EvidenceRequirement("A","F","I","R","Requirement","Guidance",EvidenceRequirement.EvidenceType.DOCUMENT,null,0,true,false,1)).hasMessageContaining("freshnessDays");var f=new EvidenceFrameworkVersion("A","F",1,null,"Framework",null,"CSC","basis","authority","disclaimer");assertThatThrownBy(()->f.publish(LocalDate.of(2026,2,1),LocalDate.of(2026,1,1),"admin",Instant.now())).hasMessageContaining("effectiveTo");}
}
